/* Draft, preview, publish and restore. Server authorization is required for every request. */
(() => {
 'use strict';
 const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),clone=v=>JSON.parse(JSON.stringify(v));
 const featureNames={constellations:'Constellations',missions:'Missions',journey:'Voyage des Univers',awakening:'Atelier d’Éveil',sanctuary:'Sanctuaire',events:'Événements'};
 let owner='',epoch=0,busy=false,record=null,draft=null,dirty=false,selected=new Set();
 const account=()=>window.KizunaAccount?.getSnapshot?.()||{},allowed=()=>account().isAdmin===true&&!account().loading&&!!account().user?.id;
 const cards=()=>window.KizunaGame?.getSnapshot?.().cards||[];
 const dateInput=v=>v?new Date(v).toISOString().slice(0,16):'';
 const status=(text,error=false)=>{if($('ksuStatus')){$('ksuStatus').textContent=text;$('ksuStatus').classList.toggle('is-error',error);}};
 function mount(){const next=allowed()?account().user.id:'',host=$('staffPage');if(next!==owner||!next){$('ksuTab')?.remove();$('ks-studio')?.remove();owner=next;epoch++;busy=false;record=null;draft=null;dirty=false;selected.clear();}if(!next||!host?.querySelector('.ks-tabs')||$('ks-studio'))return;
  const tab=document.createElement('button');tab.id='ksuTab';tab.type='button';tab.dataset.ksTab='studio';tab.textContent='Studio Kizuna';tab.setAttribute('aria-controls','ks-studio');tab.setAttribute('aria-pressed','false');host.querySelector('.ks-tabs').append(tab);
  const panel=document.createElement('section');panel.id='ks-studio';panel.className='ks-panel ksu-studio';panel.hidden=true;panel.innerHTML='<header class="ksu-heading"><div><span class="ksu-kicker">DIRECTION DU CLUB</span><h2>Studio Kizuna</h2><p>Prépare la présentation et les options cosmétiques du site, puis publie quand le résultat te convient.</p></div><button class="ks-button ks-secondary" id="ksuRefresh" type="button">Actualiser</button></header><p id="ksuStatus" role="status" aria-live="polite"></p><div id="ksuWorkspace"></div>';host.querySelector('.ks-wrap').append(panel);
  tab.addEventListener('click',()=>{if(!record)request('get');});$('ksuRefresh').addEventListener('click',()=>{if(!dirty||confirm('Recharger le brouillon enregistré et abandonner tes modifications non enregistrées ?'))request('get');});
  panel.addEventListener('submit',e=>{if(e.target.id!=='ksuForm')return;e.preventDefault();if(!allowed()||busy||!e.target.reportValidity())return;try{capture();request('save',{revision:record.revision,config:draft});}catch(error){status(error.message,true);}});
  panel.addEventListener('input',e=>{if(!draft||busy)return;if(e.target.id==='ksuCardSearch'){cardSelection();return;}if(e.target.id==='ksuArtSearch'){artOptions();return;}dirty=true;capture();preview();controls();});
  panel.addEventListener('change',e=>{if(!draft||busy)return;if(e.target.matches('[data-ksu-eligible]')){e.target.checked?selected.add(e.target.value):selected.delete(e.target.value);}dirty=true;capture();preview();controls();if(e.target.name==='awakeningMode')cardSelection();});
  panel.addEventListener('click',e=>{const b=e.target.closest('[data-ksu-admin]');if(!b||b.disabled||busy||!allowed())return;const action=b.dataset.ksuAdmin;
   if(action==='publish'){if(!dirty&&confirm('Publier ce brouillon pour tous les joueurs ? Les collections, Chakra et boosters restent inchangés.'))request('publish',{revision:record.revision});}
   if(action==='add-art'){capture();if(draft.variants.length>=50){status('Cinquante illustrations maximum.',true);return;}const card=cards()[0];if(!card)return;draft.variants.push({id:'art-'+crypto.randomUUID().slice(0,8),card_id:card.id,label:'Nouvelle illustration',image:'',source:'',level:1,enabled:false,approved:false});dirty=true;form();}
   if(action==='remove-art'){capture();draft.variants=draft.variants.filter(v=>v.id!==b.dataset.id);dirty=true;form();}
   if(action==='restore'&&confirm('Préparer cette ancienne version comme nouveau brouillon ? La version publique ne changera qu’après publication.'))request('restore',{revision:record.revision,target:b.dataset.revision});
  });
 }
 function controls(){const root=$('ks-studio');if(!root)return;root.querySelectorAll('input,select,textarea,button').forEach(n=>n.disabled=busy);if($('ksuPublish'))$('ksuPublish').disabled=busy||dirty||!record||record.revision===record.publishedRevision;root.setAttribute('aria-busy',String(busy));if($('ksuDraftState'))$('ksuDraftState').textContent=dirty?'Modifications non enregistrées':record?'Brouillon v'+record.revision+' · version publiée v'+record.publishedRevision:'';}
 async function request(action,payload={}){if(busy||!allowed())return;const token=epoch,id=owner;busy=true;controls();status(action==='get'?'Chargement du studio…':action==='publish'?'Publication…':'Enregistrement…');
  try{const result=await window.KizunaAccount.studioRequest(action,payload);if(token!==epoch||id!==owner||!allowed())return;record=result;draft=clone(result.draft);selected=new Set(draft.awakening.card_ids);dirty=false;form();if(action==='publish')window.KizunaStudio.accept(result.live);status(action==='publish'?'La configuration est publiée. Les visiteurs la reçoivent au prochain chargement ou dans la minute.':action==='restore'?'Ancienne version préparée en brouillon. Vérifie l’aperçu avant de publier.':'Brouillon prêt.');}
  catch(error){if(token===epoch)status(error.message||'Le studio est indisponible.',true);}
  finally{if(token===epoch){busy=false;controls();}}
 }
 const options=(selectedId,all=false,query='')=>{const rows=cards(),selectedCard=rows.find(c=>c.id===selectedId),matches=rows.filter(c=>(c.name+' '+c.series).toLocaleLowerCase('fr').includes(query.toLocaleLowerCase('fr'))).slice(0,all?2000:60),list=selectedCard&&!matches.some(c=>c.id===selectedId)?[selectedCard,...matches]:matches;return list.map(c=>'<option value="'+esc(c.id)+'" '+(c.id===selectedId?'selected':'')+'>'+esc(c.name)+' · '+esc(c.series)+'</option>').join('');};
 function form(){const b=draft.banner,a=draft.awakening;selected=new Set(a.card_ids);
  $('ksuWorkspace').innerHTML='<form id="ksuForm"><div class="ksu-toolbar"><p id="ksuDraftState"></p><button type="submit" class="ks-button">Enregistrer le brouillon</button><button type="button" class="ks-button" id="ksuPublish" data-ksu-admin="publish">Publier le brouillon</button></div><div class="ksu-layout"><div><fieldset><legend>Ambiance du site</legend><label>Palette<select name="theme">'+[['night','Nuit Kizuna · violet et or'],['aurora','Aurore · jade et lumière'],['ember','Crépuscule · cuivre et rose']].map(([id,label])=>'<option value="'+id+'" '+(draft.theme===id?'selected':'')+'>'+label+'</option>').join('')+'</select></label><p>Trois palettes lisibles. Les couleurs des raretés restent distinctes.</p></fieldset><fieldset><legend>Bannière d’accueil</legend><label class="ksu-check"><input name="bannerEnabled" type="checkbox" '+(b.enabled?'checked':'')+'> Afficher la bannière</label><label>Titre<input name="bannerTitle" maxlength="90" minlength="2" value="'+esc(b.title)+'" required></label><label>Message<textarea name="bannerBody" maxlength="400">'+esc(b.body)+'</textarea></label><label>Personnage illustré<select name="bannerCard"><option value="">Sans personnage</option>'+options(b.card_id,true)+'</select></label><label>Destination du bouton<select name="bannerTarget">'+Object.entries({...featureNames,boosters:'Boosters',collection:'Collection'}).filter(([id])=>!['awakening','sanctuary'].includes(id)).map(([id,label])=>'<option value="'+id+'" '+(b.target===id?'selected':'')+'>'+label+'</option>').join('')+'</select></label><div class="ksu-pair"><label>Début · UTC<input name="bannerStart" type="datetime-local" value="'+dateInput(b.starts_at)+'"></label><label>Fin · UTC<input name="bannerEnd" type="datetime-local" value="'+dateInput(b.ends_at)+'"></label></div></fieldset><fieldset><legend>Activités disponibles</legend><p>Désactiver une activité conserve les récompenses et la progression déjà acquises.</p><div class="ksu-features">'+Object.entries(featureNames).map(([id,label])=>'<label class="ksu-check"><input name="feature_'+id+'" type="checkbox" '+(draft.features[id]?'checked':'')+'> '+label+'</label>').join('')+'</div></fieldset></div><aside><h3>Aperçu du brouillon</h3><div id="ksuPreview" class="ksu-preview"></div><p class="ksu-note">Cet aperçu ne modifie pas le site public. Les dates de la bannière utilisent UTC.</p><fieldset><legend>Éligibilité à l’Éveil</legend><label>Cartes autorisées<select name="awakeningMode"><option value="all" '+(a.mode==='all'?'selected':'')+'>Toutes les cartes</option><option value="selected" '+(a.mode==='selected'?'selected':'')+'>Une sélection de cartes</option></select></label><div id="ksuEligibility"><label>Rechercher un personnage ou un anime<input type="search" id="ksuCardSearch" placeholder="Bleach, Naruto…"></label><p id="ksuSelectedCount"></p><div id="ksuCardChoices" class="ksu-choices"></div></div></fieldset><fieldset><legend>Fragments d’Éveil · optionnel</legend><label class="ksu-check"><input name="fragments" type="checkbox" '+(a.fragments?'checked':'')+'> Activer les fragments</label><p>Un fragment par nouveau défi réclamé après activation. Deux fragments pour l’Éveil, cinq pour la Transcendance, avec au moins un exemplaire disponible. Les doublons restent une autre voie : 2 puis 5 exemplaires, sans consommation.</p><p>Aucun achat de fragments ni conversion de Chakra. Les anciens défis ne sont pas recrédités.</p></fieldset></aside></div><fieldset><legend>Illustrations alternatives</legend><p>Ajoute une image et sa source, vérifie son attribution et coche la validation de l’équipe avant de l’activer. Les joueurs la choisissent dans l’Atelier d’Éveil.</p><label>Filtrer les personnages des illustrations<input id="ksuArtSearch" type="search" placeholder="Personnage ou anime"></label><div id="ksuVariants">'+draft.variants.map(v=>'<article class="ksu-variant" data-ksu-variant="'+esc(v.id)+'"><div class="ksu-pair"><label>Personnage<select name="card_id">'+options(v.card_id)+'</select></label><label>Nom de la version<input name="label" value="'+esc(v.label)+'" minlength="2" maxlength="80" required></label></div><label>Image HTTPS · PNG, JPG, WebP ou AVIF<input name="image" type="url" value="'+esc(v.image)+'" placeholder="https://…/illustration.webp" required></label><label>Source ou attribution<input name="source" type="url" value="'+esc(v.source)+'" placeholder="https://…" required></label><label>Déblocage<select name="level">'+[['0','Carte possédée'],['1','Éveil'],['2','Transcendance']].map(([id,label])=>'<option value="'+id+'" '+(Number(id)===v.level?'selected':'')+'>'+label+'</option>').join('')+'</select></label><div class="ksu-features"><label class="ksu-check"><input name="approved" type="checkbox" '+(v.approved?'checked':'')+'> Illustration validée par l’équipe</label><label class="ksu-check"><input name="enabled" type="checkbox" '+(v.enabled?'checked':'')+'> Disponible après publication</label></div><button type="button" class="ks-button ks-secondary" data-ksu-admin="remove-art" data-id="'+esc(v.id)+'">Retirer du brouillon</button></article>').join('')+'</div><button type="button" class="ks-button ks-secondary" data-ksu-admin="add-art">Ajouter une illustration</button></fieldset></form><details class="ksu-history"><summary>Historique et restauration · 20 dernières versions</summary>'+record.history.map(h=>'<div><span>v'+h.revision+' · '+esc(({initial:'Initiale',save:'Brouillon',publish:'Publiée',restore:'Restaurée'})[h.action]||h.action)+' · '+esc(new Date(h.created_at).toLocaleString('fr-FR'))+'</span><button type="button" class="ks-button ks-secondary" data-ksu-admin="restore" data-revision="'+h.revision+'">Reprendre en brouillon</button></div>').join('')+'</details>';
  cardSelection();preview();controls();
  const oldEligibility=$('ksuForm').elements.awakeningMode?.closest('fieldset'),oldFragments=$('ksuForm').elements.fragments?.closest('fieldset');
  if(oldEligibility)oldEligibility.hidden=true;if(oldFragments)oldFragments.hidden=true;
 }
 function capture(){const form=$('ksuForm');if(!form)return;const f=form.elements;
  draft.theme=f.theme.value;for(const key of Object.keys(featureNames))draft.features[key]=f['feature_'+key].checked;
  draft.banner={enabled:f.bannerEnabled.checked,title:f.bannerTitle.value,body:f.bannerBody.value,card_id:f.bannerCard.value,target:f.bannerTarget.value,starts_at:f.bannerStart.value?f.bannerStart.value+':00Z':null,ends_at:f.bannerEnd.value?f.bannerEnd.value+':00Z':null};
  draft.awakening={mode:f.awakeningMode.value,card_ids:[...selected],fragments:f.fragments.checked};
  draft.variants=[...form.querySelectorAll('[data-ksu-variant]')].map(row=>{const get=name=>row.querySelector('[name="'+name+'"]');return {id:row.dataset.ksuVariant,card_id:get('card_id').value,label:get('label').value,image:get('image').value,source:get('source').value,level:Number(get('level').value),enabled:get('enabled').checked,approved:get('approved').checked};});
 }
 function cardSelection(){if(!$('ksuEligibility'))return;$('ksuEligibility').hidden=draft.awakening.mode!=='selected';const query=($('ksuCardSearch')?.value||'').toLocaleLowerCase('fr');const rows=cards().filter(c=>(c.name+' '+c.series).toLocaleLowerCase('fr').includes(query)).sort((a,b)=>Number(selected.has(b.id))-Number(selected.has(a.id))||a.name.localeCompare(b.name,'fr')).slice(0,60);$('ksuSelectedCount').textContent=selected.size+' carte(s) sélectionnée(s) · 60 résultats maximum';$('ksuCardChoices').innerHTML=rows.map(c=>'<label class="ksu-check"><input data-ksu-eligible type="checkbox" value="'+esc(c.id)+'" '+(selected.has(c.id)?'checked':'')+'>'+esc(c.name)+' · '+esc(c.series)+'</label>').join('')||'<p>Aucun personnage trouvé.</p>';}
 function artOptions(){const query=$('ksuArtSearch').value;document.querySelectorAll('[data-ksu-variant] select[name="card_id"]').forEach(s=>s.innerHTML=options(s.value,false,query));}
 function preview(){if(!$('ksuPreview'))return;const b=draft.banner,c=cards().find(c=>c.id===b.card_id);$('ksuPreview').dataset.theme=draft.theme;$('ksuPreview').innerHTML='<span class="ksu-kicker">KIZUNA</span><h3>'+esc(b.title)+'</h3><p>'+esc(b.body||'Chaque carte crée un lien.')+'</p>'+(c?'<img src="'+esc(c.image)+'" alt="'+esc(c.name)+'" loading="lazy">':'<div class="ksu-preview-mark" aria-hidden="true">絆</div>')+'<span class="soft-btn">Découvrir →</span><small>'+(!b.enabled?'Bannière masquée sur le site':b.starts_at?'Bannière programmée':'Bannière activée')+'</small>';if($('ksuSelectedCount'))$('ksuSelectedCount').textContent=selected.size+' carte(s) sélectionnée(s) · 60 résultats maximum';}
 new MutationObserver(mount).observe(document.querySelector('main'),{subtree:true,childList:true});document.addEventListener('kizuna:account-change',mount);mount();
})();
